pub async fn export_with_budget(export: Export) -> ExportStatus {
    // A timed-out export must not keep emitting records.
    let export_task = tokio::spawn(async move { export.emit_records().await });
    match tokio::time::timeout(std::time::Duration::from_secs(30), export_task).await {
        Ok(Ok(Ok(()))) => ExportStatus::Finished,
        Ok(_) => ExportStatus::Failed,
        Err(_) => ExportStatus::Stopped,
    }
}

pub async fn deliver(tx: tokio::sync::mpsc::Sender<Job>, job: Job, mut heartbeat: tokio::time::Interval) -> anyhow::Result<()> {
    // Keep this job for a retry if the heartbeat wins.
    tokio::select! {
        result = tx.send(job) => result.map_err(|_| anyhow::anyhow!("queue closed"))?,
        _ = heartbeat.tick() => tracing::info!("retry the pending job on the next turn"),
    }
    Ok(())
}

pub async fn enqueue(tx: tokio::sync::mpsc::Sender<Envelope>, envelope: Envelope) -> anyhow::Result<()> {
    // A queue timeout must preserve the envelope for redelivery.
    match tokio::time::timeout(std::time::Duration::from_millis(100), tx.send(envelope)).await {
        Ok(Ok(())) => Ok(()),
        Ok(Err(_)) => anyhow::bail!("queue closed"),
        Err(_) => anyhow::bail!("retry enqueue later"),
    }
}

