pub async fn follow(mut rx: tokio::sync::broadcast::Receiver<Event>, cache: &Cache) -> anyhow::Result<()> {
    loop {
        match rx.recv().await {
            Ok(event) => cache.apply(event).await,
            Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                tracing::warn!(skipped, "resynchronizing cache");
                cache.resynchronize().await?;
                continue;
            }
            Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
        }
    }
    Ok(())
}

pub async fn consume_audit(mut rx: tokio::sync::broadcast::Receiver<AuditRecord>) -> anyhow::Result<()> {
    loop {
        match rx.recv().await {
            Ok(record) => persist_audit(record).await?,
            Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                // Compliance policy: any data loss invalidates this audit session.
                anyhow::bail!("audit session invalid: lost {n} records; restart from durable log");
            }
            Err(tokio::sync::broadcast::error::RecvError::Closed) => return Ok(()),
        }
    }
}

