pub async fn enqueue_reliably(tx: tokio::sync::mpsc::Sender<Job>, job: Job, mut tick: tokio::time::Interval) -> anyhow::Result<()> {
    loop {
        tokio::select! {
            permit = tx.reserve() => {
                permit.map_err(|_| anyhow::anyhow!("closed"))?.send(job);
                return Ok(());
            }
            _ = tick.tick() => tracing::debug!("still retaining job while queue is full"),
        }
    }
}

pub async fn enqueue_retained(tx: tokio::sync::mpsc::Sender<Job>, job: Job, mut tick: tokio::time::Interval) -> anyhow::Result<()> {
    let pending_send = tx.send(job);
    tokio::pin!(pending_send);
    loop {
        tokio::select! {
            result = &mut pending_send => return result.map_err(|_| anyhow::anyhow!("closed")),
            _ = tick.tick() => tracing::debug!("same send future remains pending"),
        }
    }
}

